:root {
  --ink: #172033;
  --muted: #6c7180;
  --surface: #ffffff;
  --line: #dfe3ec;
  --violet: #6d4aff;
  --violet-soft: #eeeaff;
  --lime: #b8f34b;
  --lime-ink: #253500;
}

.score-card {
  width: 480px;
  box-sizing: border-box;
  padding: 16px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 18px;
  color: var(--ink);
}

.card-header,
.card-footer,
.brand,
.player {
  display: flex;
  align-items: center;
}

.card-header,
.card-footer {
  justify-content: space-between;
}

.brand,
.player {
  gap: 10px;
}

.game-icon,
.avatar {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
}

.game-icon {
  width: 38px;
  height: 38px;
  background: var(--violet-soft);
  border-radius: 11px;
  font-size: 20px;
}

.eyebrow,
.score-label,
.rank-label {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.9px;
}

.card-header h1 {
  margin: 2px 0 0;
  font-size: 19px;
  line-height: 1.1;
}

.status {
  padding: 5px 8px;
  background: var(--lime);
  border-radius: 999px;
  color: var(--lime-ink);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.5px;
}

.score-grid {
  display: grid;
  grid-template-columns: 1fr 138px;
  gap: 10px;
  margin: 15px 0;
}

.score-main,
.rank-panel {
  padding: 14px;
  border-radius: 13px;
}

.score-main {
  background: var(--violet);
}

.score-main .score-label {
  color: var(--violet-soft);
}

.score-value {
  display: block;
  margin-top: 5px;
  color: var(--surface);
  font-size: 29px;
  line-height: 1;
  letter-spacing: -1px;
}

.rank-panel {
  background: var(--violet-soft);
}

.rank-value {
  display: block;
  margin-top: 5px;
  font-size: 24px;
  line-height: 1;
}

.rank-note {
  display: inline-block;
  margin-top: 7px;
  color: var(--violet);
  font-size: 11px;
  font-weight: 700;
}

.card-footer {
  padding-top: 13px;
  border-top: 1px solid var(--line);
}

.avatar {
  width: 30px;
  height: 30px;
  background: var(--ink);
  border-radius: 50%;
  color: var(--surface);
  font-size: 13px;
  font-weight: 800;
}

.player strong,
.player span {
  display: block;
}

.player strong {
  font-size: 13px;
  line-height: 1.2;
}

.player span {
  margin-top: 2px;
  color: var(--muted);
  font-size: 11px;
}

.claim-button {
  padding: 8px 11px;
  border: 0;
  border-radius: 9px;
  background: var(--ink);
  color: var(--surface);
  font-size: 12px;
  font-weight: 700;
}
